from taf.cloud.lcmaas.schemas.schema_base import SchemaObject, SchemaField


class CertInfoV1(SchemaObject):
    cert_name = SchemaField(name="name", not_null=True)
    peer_type = SchemaField(name="peer_type", not_null=True)
    peer_name = SchemaField(name="peer_name", not_null=True)
    cert_type = SchemaField(name="cert_type", not_null=True)
    cert_content = SchemaField(name="content", not_null=True)

    def __init__(self, cert_name, peer_type, peer_name, cert_type, cert_content):
        self.cert_name = cert_name
        self.peer_type = peer_type
        self.peer_name = peer_name
        self.cert_type = cert_type
        self.cert_content = cert_content

        super(CertInfoV1, self).__init__()
